// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title InventoryVault
 * @author X3 Chain Team
 * @notice Capital management vault for cross-VM atomic swap collateral.
 *
 * Holds pre-funded inventory that can be used when flashloans fail or
 * as margin for atomic swap operations. Tracks PnL per asset and
 * enforces maximum exposure limits.
 *
 * ## Features
 *
 * - Multi-asset inventory with per-asset caps
 * - Role-based access (OPERATOR can draw, ADMIN can configure)
 * - Exposure tracking and auto-rebalancing triggers
 * - Emergency kill-switch (GUARDIAN pause)
 * - Cross-VM settlement integration via X3 kernel
 */
contract InventoryVault is ReentrancyGuard, AccessControl, Pausable {
    using SafeERC20 for IERC20;

    // ═══ Roles ═══════════════════════════════════════════════════════════════
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    // ═══ Types ═══════════════════════════════════════════════════════════════

    /// @notice Per-asset inventory state.
    struct AssetInventory {
        uint256 balance;         // Current balance
        uint256 maxExposure;     // Maximum allowed draw (50% of balance by default)
        uint256 totalDrawn;      // Currently drawn by operations
        uint256 totalReturned;   // Total returned (for PnL tracking)
        uint256 totalPnL;        // Cumulative PnL (positive = profit)
        bool    enabled;         // Whether draws are allowed
    }

    // ═══ State ═══════════════════════════════════════════════════════════════

    /// @notice Inventory state per asset.
    mapping(address => AssetInventory) public inventories;

    /// @notice Supported assets list.
    address[] public assets;

    /// @notice Maximum exposure percentage (basis points, default 5000 = 50%).
    uint256 public maxExposureBps = 5000;

    // ═══ Events ══════════════════════════════════════════════════════════════

    event Deposited(address indexed asset, uint256 amount, address indexed from);
    event Withdrawn(address indexed asset, uint256 amount, address indexed to);
    event Drawn(address indexed asset, uint256 amount, bytes32 indexed operationId);
    event Returned(address indexed asset, uint256 amount, uint256 pnl, bytes32 indexed operationId);
    event AssetConfigured(address indexed asset, uint256 maxExposure, bool enabled);
    event ExposureLimitHit(address indexed asset, uint256 attempted, uint256 available);

    // ═══ Errors ══════════════════════════════════════════════════════════════

    error AssetNotEnabled();
    error InsufficientBalance();
    error ExposureLimitExceeded();
    error InvalidAmount();

    // ═══ Constructor ═════════════════════════════════════════════════════════

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE, msg.sender);
    }

    // ═══ Deposit/Withdraw (Admin) ════════════════════════════════════════════

    /**
     * @notice Deposit inventory capital.
     */
    function deposit(
        address asset,
        uint256 amount
    ) external nonReentrant whenNotPaused onlyRole(DEFAULT_ADMIN_ROLE) {
        if (amount == 0) revert InvalidAmount();

        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);

        AssetInventory storage inv = inventories[asset];
        if (!inv.enabled) {
            // Auto-enable on first deposit
            inv.enabled = true;
            inv.maxExposure = (amount * maxExposureBps) / 10000;
            assets.push(asset);
        }
        inv.balance += amount;

        emit Deposited(asset, amount, msg.sender);
    }

    /**
     * @notice Withdraw idle inventory.
     */
    function withdraw(
        address asset,
        uint256 amount,
        address to
    ) external nonReentrant onlyRole(DEFAULT_ADMIN_ROLE) {
        AssetInventory storage inv = inventories[asset];
        uint256 available = inv.balance - inv.totalDrawn;
        if (amount > available) revert InsufficientBalance();

        inv.balance -= amount;
        IERC20(asset).safeTransfer(to, amount);

        emit Withdrawn(asset, amount, to);
    }

    // ═══ Draw/Return (Operator — used by swap coordinator) ═══════════════════

    /**
     * @notice Draw inventory for an atomic swap operation.
     * @param asset      Asset to draw
     * @param amount     Amount to draw
     * @param operationId Unique identifier for the swap operation
     */
    function draw(
        address asset,
        uint256 amount,
        bytes32 operationId
    ) external nonReentrant whenNotPaused onlyRole(OPERATOR_ROLE) {
        AssetInventory storage inv = inventories[asset];
        if (!inv.enabled) revert AssetNotEnabled();

        uint256 available = inv.balance - inv.totalDrawn;
        if (amount > available) revert InsufficientBalance();

        if (inv.totalDrawn + amount > inv.maxExposure) {
            emit ExposureLimitHit(asset, amount, inv.maxExposure - inv.totalDrawn);
            revert ExposureLimitExceeded();
        }

        inv.totalDrawn += amount;
        IERC20(asset).safeTransfer(msg.sender, amount);

        emit Drawn(asset, amount, operationId);
    }

    /**
     * @notice Return capital after a swap operation (may include PnL).
     * @param asset      Asset being returned
     * @param amount     Amount returned (may differ from drawn amount)
     * @param drawnAmount Original amount drawn (for PnL calculation)
     * @param operationId Unique identifier for the swap operation
     */
    function returnCapital(
        address asset,
        uint256 amount,
        uint256 drawnAmount,
        bytes32 operationId
    ) external nonReentrant onlyRole(OPERATOR_ROLE) {
        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);

        AssetInventory storage inv = inventories[asset];
        inv.balance = inv.balance - drawnAmount + amount;
        inv.totalDrawn -= drawnAmount;
        inv.totalReturned += amount;

        // Track PnL
        if (amount > drawnAmount) {
            inv.totalPnL += (amount - drawnAmount);
        }

        emit Returned(asset, amount, amount > drawnAmount ? amount - drawnAmount : 0, operationId);
    }

    // ═══ Admin ═══════════════════════════════════════════════════════════════

    function configureAsset(
        address asset,
        uint256 _maxExposure,
        bool _enabled
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        AssetInventory storage inv = inventories[asset];
        inv.maxExposure = _maxExposure;
        inv.enabled = _enabled;
        emit AssetConfigured(asset, _maxExposure, _enabled);
    }

    function setMaxExposureBps(uint256 _bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_bps <= 10000, "Max 100%");
        maxExposureBps = _bps;
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(GUARDIAN_ROLE) {
        _unpause();
    }

    // ═══ Views ═══════════════════════════════════════════════════════════════

    function getAvailable(address asset) external view returns (uint256) {
        AssetInventory storage inv = inventories[asset];
        return inv.balance - inv.totalDrawn;
    }

    function getExposure(address asset) external view returns (uint256 drawn, uint256 maxExp) {
        AssetInventory storage inv = inventories[asset];
        return (inv.totalDrawn, inv.maxExposure);
    }

    function getPnL(address asset) external view returns (uint256) {
        return inventories[asset].totalPnL;
    }

    function getAssetCount() external view returns (uint256) {
        return assets.length;
    }
}

contracts/src/FeeManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title FeeManager
 * @notice Centralized fee collection and distribution for X3 Chain
 * @dev Handles protocol fees from DEX, bridges, flash loans, and distributes to stakeholders
 * 
 * Fee Distribution:
 * - Validators: 40% (staking rewards)
 * - Treasury: 30% (protocol development)
 * - Buyback & Burn: 15% (deflationary pressure)
 * - Insurance Fund: 15% (security reserve)
 */
contract FeeManager is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ═══════════════════════════════════════════════════════════════════════════
    // ROLES
    // ═══════════════════════════════════════════════════════════════════════════

    bytes32 public constant COLLECTOR_ROLE = keccak256("COLLECTOR_ROLE");
    bytes32 public constant DISTRIBUTOR_ROLE = keccak256("DISTRIBUTOR_ROLE");
    bytes32 public constant FEE_SETTER_ROLE = keccak256("FEE_SETTER_ROLE");

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTANTS
    // ═══════════════════════════════════════════════════════════════════════════

    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant MAX_FEE_BPS = 1000; // 10% max fee

    // Fee types
    uint8 public constant FEE_TYPE_SWAP = 0;
    uint8 public constant FEE_TYPE_BRIDGE = 1;
    uint8 public constant FEE_TYPE_FLASH_LOAN = 2;
    uint8 public constant FEE_TYPE_ATOMIC_SWAP = 3;
    uint8 public constant FEE_TYPE_CROSS_VM = 4;

    // ═══════════════════════════════════════════════════════════════════════════
    // STATE
    // ═══════════════════════════════════════════════════════════════════════════

    // Distribution addresses
    address public validatorRewardsPool;
    address public treasury;
    address public buybackContract;
    address public insuranceFund;

    // Distribution shares (in BPS)
    uint256 public validatorShareBps = 4000;  // 40%
    uint256 public treasuryShareBps = 3000;   // 30%
    uint256 public buybackShareBps = 1500;    // 15%
    uint256 public insuranceShareBps = 1500;  // 15%

    // Fee rates per type (in BPS)
    mapping(uint8 => uint256) public feeRates;

    // Accumulated fees per token
    mapping(address => uint256) public accumulatedFees;

    // Supported fee tokens
    mapping(address => bool) public supportedTokens;
    address[] public tokenList;

    // Native token (X3)
    address public x3Token;

    // Fee collection stats
    struct FeeStats {
        uint256 totalCollected;
        uint256 totalDistributed;
        uint256 lastDistribution;
        uint256 distributionCount;
    }
    mapping(address => FeeStats) public tokenStats;

    // Distribution history
    struct Distribution {
        uint256 timestamp;
        address token;
        uint256 amount;
        uint256 validatorAmount;
        uint256 treasuryAmount;
        uint256 buybackAmount;
        uint256 insuranceAmount;
    }
    Distribution[] public distributions;

    // Referral fee sharing - token-aware: referrer => token => balance
    mapping(address => mapping(address => uint256)) public referralBalances;
    uint256 public referralShareBps = 500; // 5% of fees to referrers

    // ═══════════════════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════════════════

    event FeeCollected(
        address indexed token,
        uint256 amount,
        uint8 feeType,
        address indexed source
    );

    event FeesDistributed(
        address indexed token,
        uint256 totalAmount,
        uint256 validatorAmount,
        uint256 treasuryAmount,
        uint256 buybackAmount,
        uint256 insuranceAmount
    );

    event FeeRateUpdated(uint8 feeType, uint256 oldRate, uint256 newRate);
    event DistributionSharesUpdated(
        uint256 validator,
        uint256 treasury,
        uint256 buyback,
        uint256 insurance
    );
    event TokenAdded(address indexed token);
    event TokenRemoved(address indexed token);
    event ReferralPaid(address indexed referrer, address indexed token, uint256 amount);
    event DistributionAddressUpdated(string addressType, address newAddress);

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════════

    constructor(
        address _x3Token,
        address _validatorRewardsPool,
        address _treasury,
        address _buybackContract,
        address _insuranceFund
    ) {
        require(_x3Token != address(0), "Invalid X3 token");
        require(_validatorRewardsPool != address(0), "Invalid validator pool");
        require(_treasury != address(0), "Invalid treasury");
        require(_buybackContract != address(0), "Invalid buyback");
        require(_insuranceFund != address(0), "Invalid insurance");

        x3Token = _x3Token;
        validatorRewardsPool = _validatorRewardsPool;
        treasury = _treasury;
        buybackContract = _buybackContract;
        insuranceFund = _insuranceFund;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(COLLECTOR_ROLE, msg.sender);
        _grantRole(DISTRIBUTOR_ROLE, msg.sender);
        _grantRole(FEE_SETTER_ROLE, msg.sender);

        // Set default fee rates
        feeRates[FEE_TYPE_SWAP] = 30;          // 0.30%
        feeRates[FEE_TYPE_BRIDGE] = 10;        // 0.10%
        feeRates[FEE_TYPE_FLASH_LOAN] = 9;     // 0.09%
        feeRates[FEE_TYPE_ATOMIC_SWAP] = 15;   // 0.15%
        feeRates[FEE_TYPE_CROSS_VM] = 5;       // 0.05%

        // Add X3 as supported token
        supportedTokens[_x3Token] = true;
        tokenList.push(_x3Token);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // FEE COLLECTION
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Collect fees from a protocol operation
     * @param token The fee token
     * @param amount The fee amount
     * @param feeType The type of fee
     * @param referrer Optional referrer for fee sharing
     */
    function collectFee(
        address token,
        uint256 amount,
        uint8 feeType,
        address referrer
    ) external nonReentrant whenNotPaused onlyRole(COLLECTOR_ROLE) {
        require(supportedTokens[token], "Token not supported");
        require(amount > 0, "Zero amount");

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        // Handle referral share - store per-token
        uint256 referralAmount = 0;
        if (referrer != address(0) && referrer != msg.sender) {
            referralAmount = (amount * referralShareBps) / BPS_DENOMINATOR;
            referralBalances[referrer][token] += referralAmount;
            amount -= referralAmount;
        }

        accumulatedFees[token] += amount;
        tokenStats[token].totalCollected += amount;

        emit FeeCollected(token, amount, feeType, msg.sender);
    }

    /**
     * @notice Collect native ETH/gas token fees
     */
    function collectNativeFee(
        uint8 feeType,
        address referrer
    ) external payable nonReentrant whenNotPaused {
        require(msg.value > 0, "Zero value");

        uint256 amount = msg.value;
        uint256 referralAmount = 0;

        if (referrer != address(0) && referrer != msg.sender) {
            referralAmount = (amount * referralShareBps) / BPS_DENOMINATOR;
            // Store native referral balance (mapped to address(0))
            referralBalances[referrer][address(0)] += referralAmount;
            amount -= referralAmount;
        }

        accumulatedFees[address(0)] += amount;
        tokenStats[address(0)].totalCollected += amount;

        emit FeeCollected(address(0), amount, feeType, msg.sender);
    }

    /**
     * @notice Calculate fee for a given amount and type
     */
    function calculateFee(
        uint256 amount,
        uint8 feeType
    ) external view returns (uint256) {
        return (amount * feeRates[feeType]) / BPS_DENOMINATOR;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // FEE DISTRIBUTION
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Distribute accumulated fees for a token
     * @param token The token to distribute
     */
    function distributeFees(
        address token
    ) external nonReentrant whenNotPaused onlyRole(DISTRIBUTOR_ROLE) {
        _distributeFees(token);
    }

    /**
     * @notice Internal fee distribution logic
     * @param token The token to distribute
     */
    function _distributeFees(address token) internal {
        uint256 amount = accumulatedFees[token];
        require(amount > 0, "No fees to distribute");

        accumulatedFees[token] = 0;

        uint256 validatorAmount = (amount * validatorShareBps) / BPS_DENOMINATOR;
        uint256 treasuryAmount = (amount * treasuryShareBps) / BPS_DENOMINATOR;
        uint256 buybackAmount = (amount * buybackShareBps) / BPS_DENOMINATOR;
        uint256 insuranceAmount = amount - validatorAmount - treasuryAmount - buybackAmount;

        if (token == address(0)) {
            // Native token distribution
            _safeTransferETH(validatorRewardsPool, validatorAmount);
            _safeTransferETH(treasury, treasuryAmount);
            _safeTransferETH(buybackContract, buybackAmount);
            _safeTransferETH(insuranceFund, insuranceAmount);
        } else {
            IERC20(token).safeTransfer(validatorRewardsPool, validatorAmount);
            IERC20(token).safeTransfer(treasury, treasuryAmount);
            IERC20(token).safeTransfer(buybackContract, buybackAmount);
            IERC20(token).safeTransfer(insuranceFund, insuranceAmount);
        }

        // Update stats
        tokenStats[token].totalDistributed += amount;
        tokenStats[token].lastDistribution = block.timestamp;
        tokenStats[token].distributionCount++;

        // Record distribution
        distributions.push(Distribution({
            timestamp: block.timestamp,
            token: token,
            amount: amount,
            validatorAmount: validatorAmount,
            treasuryAmount: treasuryAmount,
            buybackAmount: buybackAmount,
            insuranceAmount: insuranceAmount
        }));

        emit FeesDistributed(
            token,
            amount,
            validatorAmount,
            treasuryAmount,
            buybackAmount,
            insuranceAmount
        );
    }

    /**
     * @notice Distribute all accumulated fees for all tokens
     */
    function distributeAllFees() external nonReentrant whenNotPaused onlyRole(DISTRIBUTOR_ROLE) {
        // Distribute native token fees
        if (accumulatedFees[address(0)] > 0) {
            _distributeFees(address(0));
        }

        // Distribute ERC20 token fees
        for (uint256 i = 0; i < tokenList.length; i++) {
            if (accumulatedFees[tokenList[i]] > 0) {
                _distributeFees(tokenList[i]);
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // REFERRAL SYSTEM
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Claim referral rewards for a specific token
     * @param token The token to claim (address(0) for native)
     */
    function claimReferralRewards(address token) external nonReentrant whenNotPaused {
        uint256 amount = referralBalances[msg.sender][token];
        require(amount > 0, "No rewards to claim");

        referralBalances[msg.sender][token] = 0;

        if (token == address(0)) {
            _safeTransferETH(msg.sender, amount);
        } else {
            IERC20(token).safeTransfer(msg.sender, amount);
        }

        emit ReferralPaid(msg.sender, token, amount);
    }

    /**
     * @notice Get referral balance for a specific token
     * @param referrer The referrer address
     * @param token The token address (address(0) for native)
     */
    function getReferralBalance(address referrer, address token) external view returns (uint256) {
        return referralBalances[referrer][token];
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Set fee rate for a fee type
     */
    function setFeeRate(
        uint8 feeType,
        uint256 newRate
    ) external onlyRole(FEE_SETTER_ROLE) {
        require(newRate <= MAX_FEE_BPS, "Fee too high");

        uint256 oldRate = feeRates[feeType];
        feeRates[feeType] = newRate;

        emit FeeRateUpdated(feeType, oldRate, newRate);
    }

    /**
     * @notice Update distribution shares
     */
    function setDistributionShares(
        uint256 _validatorBps,
        uint256 _treasuryBps,
        uint256 _buybackBps,
        uint256 _insuranceBps
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(
            _validatorBps + _treasuryBps + _buybackBps + _insuranceBps == BPS_DENOMINATOR,
            "Shares must sum to 100%"
        );

        validatorShareBps = _validatorBps;
        treasuryShareBps = _treasuryBps;
        buybackShareBps = _buybackBps;
        insuranceShareBps = _insuranceBps;

        emit DistributionSharesUpdated(
            _validatorBps,
            _treasuryBps,
            _buybackBps,
            _insuranceBps
        );
    }

    /**
     * @notice Add a supported fee token
     */
    function addSupportedToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(!supportedTokens[token], "Already supported");
        supportedTokens[token] = true;
        tokenList.push(token);
        emit TokenAdded(token);
    }

    /**
     * @notice Remove a supported fee token
     */
    function removeSupportedToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(supportedTokens[token], "Not supported");
        require(token != x3Token, "Cannot remove X3");

        supportedTokens[token] = false;

        // Remove from list
        for (uint256 i = 0; i < tokenList.length; i++) {
            if (tokenList[i] == token) {
                tokenList[i] = tokenList[tokenList.length - 1];
                tokenList.pop();
                break;
            }
        }

        emit TokenRemoved(token);
    }

    /**
     * @notice Update distribution addresses
     */
    function setValidatorRewardsPool(address newPool) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newPool != address(0), "Invalid address");
        validatorRewardsPool = newPool;
        emit DistributionAddressUpdated("validatorRewardsPool", newPool);
    }

    function setTreasury(address newTreasury) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newTreasury != address(0), "Invalid address");
        treasury = newTreasury;
        emit DistributionAddressUpdated("treasury", newTreasury);
    }

    function setBuybackContract(address newBuyback) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newBuyback != address(0), "Invalid address");
        buybackContract = newBuyback;
        emit DistributionAddressUpdated("buybackContract", newBuyback);
    }

    function setInsuranceFund(address newInsurance) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newInsurance != address(0), "Invalid address");
        insuranceFund = newInsurance;
        emit DistributionAddressUpdated("insuranceFund", newInsurance);
    }

    function setReferralShare(uint256 newShareBps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newShareBps <= 2000, "Max 20% referral");
        referralShareBps = newShareBps;
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    function getTokenList() external view returns (address[] memory) {
        return tokenList;
    }

    function getDistributionCount() external view returns (uint256) {
        return distributions.length;
    }

    function getDistribution(uint256 index) external view returns (Distribution memory) {
        return distributions[index];
    }

    function getPendingFees(address token) external view returns (uint256) {
        return accumulatedFees[token];
    }

    function getTotalPendingFees() external view returns (uint256 total) {
        total = accumulatedFees[address(0)];
        for (uint256 i = 0; i < tokenList.length; i++) {
            total += accumulatedFees[tokenList[i]];
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // INTERNAL
    // ═══════════════════════════════════════════════════════════════════════════

    function _safeTransferETH(address to, uint256 amount) internal {
        (bool success, ) = to.call{value: amount}("");
        require(success, "ETH transfer failed");
    }

    receive() external payable {}
}

contracts/src/PriceOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title PriceOracle
 * @notice Multi-source price oracle for X3 Chain
 * @dev Aggregates prices from multiple sources with TWAP and deviation checks
 * 
 * Features:
 * - Multi-source price aggregation
 * - Time-weighted average prices (TWAP)
 * - Deviation protection
 * - Chainlink integration ready
 * - Cross-VM price feeds
 */
contract PriceOracle is AccessControl, Pausable {
    // ═══════════════════════════════════════════════════════════════════════════
    // TYPES
    // ═══════════════════════════════════════════════════════════════════════════

    struct PriceFeed {
        uint256 price;              // Price with 18 decimals
        uint256 timestamp;          // Last update time
        uint256 confidence;         // Confidence level (0-10000 BPS)
        uint8 decimals;             // Price decimals
        bool active;                // Feed is active
        address source;             // Price source address
        PriceSourceType sourceType; // Type of price source
    }

    struct TokenConfig {
        string symbol;
        uint8 decimals;
        bool active;
        uint256 heartbeat;          // Max seconds between updates
        uint256 deviationThreshold; // Max price deviation in BPS
        address[] priceSources;     // Multiple price sources
    }

    struct TWAPObservation {
        uint256 timestamp;
        uint256 price;
        uint256 cumulativePrice;
    }

    enum PriceSourceType {
        INTERNAL,       // Internal oracle updates
        CHAINLINK,      // Chainlink price feed
        UNISWAP_V3,     // Uniswap V3 TWAP
        DEX_SPOT,       // DEX spot price
        CROSS_VM        // Cross-VM price feed
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTANTS & ROLES
    // ═══════════════════════════════════════════════════════════════════════════

    bytes32 public constant PRICE_UPDATER_ROLE = keccak256("PRICE_UPDATER_ROLE");
    bytes32 public constant CONFIG_MANAGER_ROLE = keccak256("CONFIG_MANAGER_ROLE");

    uint256 public constant PRICE_PRECISION = 1e18;
    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant MAX_DEVIATION_BPS = 5000; // 50%
    uint256 public constant MIN_CONFIDENCE = 5000;    // 50%
    uint256 public constant TWAP_PERIOD = 30 minutes;
    uint256 public constant MAX_OBSERVATIONS = 24;    // Store 24 observations

    // ═══════════════════════════════════════════════════════════════════════════
    // STATE
    // ═══════════════════════════════════════════════════════════════════════════

    // Token address => Token config
    mapping(address => TokenConfig) public tokenConfigs;

    // Token address => Latest price feed
    mapping(address => PriceFeed) public latestPrices;

    // Token address => TWAP observations
    mapping(address => TWAPObservation[]) public twapObservations;

    // Token address => Source address => Price feed
    mapping(address => mapping(address => PriceFeed)) public sourcePrices;

    // Registered tokens
    address[] public registeredTokens;

    // Base token (e.g., USD stablecoin for pricing)
    address public baseToken;

    // Emergency fallback price (used when all sources fail)
    mapping(address => uint256) public fallbackPrices;

    // ═══════════════════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════════════════

    event PriceUpdated(
        address indexed token,
        uint256 price,
        uint256 timestamp,
        address indexed source,
        PriceSourceType sourceType
    );

    event TokenConfigured(
        address indexed token,
        string symbol,
        uint256 heartbeat,
        uint256 deviationThreshold
    );

    event PriceSourceAdded(
        address indexed token,
        address indexed source,
        PriceSourceType sourceType
    );

    event PriceSourceRemoved(address indexed token, address indexed source);

    event StalePrice(address indexed token, uint256 lastUpdate, uint256 heartbeat);

    event PriceDeviation(
        address indexed token,
        uint256 reportedPrice,
        uint256 aggregatedPrice,
        uint256 deviationBps
    );

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════════

    constructor(address _baseToken) {
        require(_baseToken != address(0), "Invalid base token");
        baseToken = _baseToken;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PRICE_UPDATER_ROLE, msg.sender);
        _grantRole(CONFIG_MANAGER_ROLE, msg.sender);

        // Configure base token with 1:1 price
        _configureToken(
            _baseToken,
            "USD",
            18,
            1 hours,
            100 // 1% deviation
        );

        latestPrices[_baseToken] = PriceFeed({
            price: PRICE_PRECISION,
            timestamp: block.timestamp,
            confidence: BPS_DENOMINATOR,
            decimals: 18,
            active: true,
            source: address(this),
            sourceType: PriceSourceType.INTERNAL
        });
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // PRICE UPDATES
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Update price from authorized source
     */
    function updatePrice(
        address token,
        uint256 price,
        uint256 confidence
    ) external whenNotPaused onlyRole(PRICE_UPDATER_ROLE) {
        require(tokenConfigs[token].active, "Token not configured");
        require(price > 0, "Invalid price");
        require(confidence <= BPS_DENOMINATOR, "Invalid confidence");

        _updatePrice(token, price, confidence, msg.sender, PriceSourceType.INTERNAL);
    }

    /**
     * @notice Batch update prices
     */
    function batchUpdatePrices(
        address[] calldata tokens,
        uint256[] calldata prices,
        uint256[] calldata confidences
    ) external whenNotPaused onlyRole(PRICE_UPDATER_ROLE) {
        require(
            tokens.length == prices.length && prices.length == confidences.length,
            "Array mismatch"
        );

        for (uint256 i = 0; i < tokens.length; i++) {
            if (tokenConfigs[tokens[i]].active && prices[i] > 0) {
                _updatePrice(
                    tokens[i],
                    prices[i],
                    confidences[i],
                    msg.sender,
                    PriceSourceType.INTERNAL
                );
            }
        }
    }

    /**
     * @notice Update price from DEX source
     */
    function updateDexPrice(
        address token,
        uint256 price,
        address dexSource
    ) external whenNotPaused onlyRole(PRICE_UPDATER_ROLE) {
        require(tokenConfigs[token].active, "Token not configured");
        require(price > 0, "Invalid price");

        // Store source price
        sourcePrices[token][dexSource] = PriceFeed({
            price: price,
            timestamp: block.timestamp,
            confidence: 8000, // 80% default confidence for DEX
            decimals: 18,
            active: true,
            source: dexSource,
            sourceType: PriceSourceType.DEX_SPOT
        });

        // Aggregate and update main price
        _aggregateAndUpdatePrice(token);
    }

    /**
     * @notice Update cross-VM price feed
     */
    function updateCrossVMPrice(
        address token,
        uint256 price,
        uint8 sourceVM, // 0=EVM, 1=SVM, 2=X3VM
        bytes32 sourceAddress
    ) external whenNotPaused onlyRole(PRICE_UPDATER_ROLE) {
        require(tokenConfigs[token].active, "Token not configured");
        require(price > 0, "Invalid price");

        address pseudoSource = address(uint160(uint256(sourceAddress)));

        sourcePrices[token][pseudoSource] = PriceFeed({
            price: price,
            timestamp: block.timestamp,
            confidence: 7500, // 75% confidence for cross-VM
            decimals: 18,
            active: true,
            source: pseudoSource,
            sourceType: PriceSourceType.CROSS_VM
        });

        _aggregateAndUpdatePrice(token);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // PRICE RETRIEVAL
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Get latest price for a token
     */
    function getPrice(address token) external view returns (uint256 price, uint256 timestamp) {
        PriceFeed storage feed = latestPrices[token];
        require(feed.active, "Price not available");
        require(!_isStale(token), "Price is stale");

        return (feed.price, feed.timestamp);
    }

    /**
     * @notice Get latest price with full details
     */
    function getPriceFeed(address token) external view returns (PriceFeed memory) {
        require(latestPrices[token].active, "Price not available");
        return latestPrices[token];
    }

    /**
     * @notice Get TWAP price
     */
    function getTWAP(address token) external view returns (uint256) {
        TWAPObservation[] storage observations = twapObservations[token];
        require(observations.length > 0, "No observations");

        uint256 targetTime = block.timestamp - TWAP_PERIOD;
        uint256 startIdx = 0;

        // Find oldest observation within TWAP period
        for (uint256 i = 0; i < observations.length; i++) {
            if (observations[i].timestamp >= targetTime) {
                startIdx = i;
                break;
            }
        }

        if (observations.length == 1) {
            return observations[0].price;
        }

        // Calculate TWAP
        uint256 latestIdx = observations.length - 1;
        TWAPObservation storage oldest = observations[startIdx];
        TWAPObservation storage latest = observations[latestIdx];

        uint256 timeDiff = latest.timestamp - oldest.timestamp;
        if (timeDiff == 0) {
            return latest.price;
        }

        uint256 priceDiff = latest.cumulativePrice - oldest.cumulativePrice;
        return priceDiff / timeDiff;
    }

    /**
     * @notice Get price in terms of another token
     */
    function getRelativePrice(
        address baseToken_,
        address quoteToken
    ) external view returns (uint256) {
        require(latestPrices[baseToken_].active, "Base price not available");
        require(latestPrices[quoteToken].active, "Quote price not available");

        uint256 basePrice = latestPrices[baseToken_].price;
        uint256 quotePrice = latestPrices[quoteToken].price;

        return (basePrice * PRICE_PRECISION) / quotePrice;
    }

    /**
     * @notice Check if price is stale
     */
    function isPriceStale(address token) external view returns (bool) {
        return _isStale(token);
    }

    /**
     * @notice Get price with staleness check
     */
    function getSafePrice(
        address token
    ) external view returns (uint256 price, bool isStale, uint256 confidence) {
        PriceFeed storage feed = latestPrices[token];

        return (
            feed.price,
            _isStale(token),
            feed.confidence
        );
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // TOKEN CONFIGURATION
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Configure a new token for price tracking
     */
    function configureToken(
        address token,
        string calldata symbol,
        uint8 decimals,
        uint256 heartbeat,
        uint256 deviationThreshold
    ) external onlyRole(CONFIG_MANAGER_ROLE) {
        _configureToken(token, symbol, decimals, heartbeat, deviationThreshold);
    }

    /**
     * @notice Add price source for a token
     */
    function addPriceSource(
        address token,
        address source,
        PriceSourceType sourceType
    ) external onlyRole(CONFIG_MANAGER_ROLE) {
        require(tokenConfigs[token].active, "Token not configured");

        tokenConfigs[token].priceSources.push(source);

        emit PriceSourceAdded(token, source, sourceType);
    }

    /**
     * @notice Remove price source
     */
    function removePriceSource(
        address token,
        address source
    ) external onlyRole(CONFIG_MANAGER_ROLE) {
        address[] storage sources = tokenConfigs[token].priceSources;

        for (uint256 i = 0; i < sources.length; i++) {
            if (sources[i] == source) {
                sources[i] = sources[sources.length - 1];
                sources.pop();

                delete sourcePrices[token][source];

                emit PriceSourceRemoved(token, source);
                break;
            }
        }
    }

    /**
     * @notice Set fallback price for emergency
     */
    function setFallbackPrice(
        address token,
        uint256 price
    ) external onlyRole(CONFIG_MANAGER_ROLE) {
        require(price > 0, "Invalid price");
        fallbackPrices[token] = price;
    }

    /**
     * @notice Deactivate a token
     */
    function deactivateToken(address token) external onlyRole(CONFIG_MANAGER_ROLE) {
        tokenConfigs[token].active = false;
        latestPrices[token].active = false;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    function getRegisteredTokens() external view returns (address[] memory) {
        return registeredTokens;
    }

    function getTokenConfig(address token) external view returns (TokenConfig memory) {
        return tokenConfigs[token];
    }

    function getPriceSources(address token) external view returns (address[] memory) {
        return tokenConfigs[token].priceSources;
    }

    function getSourcePrice(
        address token,
        address source
    ) external view returns (PriceFeed memory) {
        return sourcePrices[token][source];
    }

    function getTWAPObservations(
        address token
    ) external view returns (TWAPObservation[] memory) {
        return twapObservations[token];
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // ADMIN
    // ═══════════════════════════════════════════════════════════════════════════

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    function setBaseToken(address newBaseToken) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newBaseToken != address(0), "Invalid address");
        baseToken = newBaseToken;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    function _configureToken(
        address token,
        string memory symbol,
        uint8 decimals,
        uint256 heartbeat,
        uint256 deviationThreshold
    ) internal {
        require(token != address(0), "Invalid token");
        require(heartbeat > 0, "Invalid heartbeat");
        require(deviationThreshold <= MAX_DEVIATION_BPS, "Deviation too high");

        if (!tokenConfigs[token].active) {
            registeredTokens.push(token);
        }

        tokenConfigs[token] = TokenConfig({
            symbol: symbol,
            decimals: decimals,
            active: true,
            heartbeat: heartbeat,
            deviationThreshold: deviationThreshold,
            priceSources: new address[](0)
        });

        emit TokenConfigured(token, symbol, heartbeat, deviationThreshold);
    }

    function _updatePrice(
        address token,
        uint256 price,
        uint256 confidence,
        address source,
        PriceSourceType sourceType
    ) internal {
        TokenConfig storage config = tokenConfigs[token];
        PriceFeed storage currentFeed = latestPrices[token];

        // Check deviation if we have existing price
        if (currentFeed.price > 0) {
            uint256 deviation = _calculateDeviation(currentFeed.price, price);

            if (deviation > config.deviationThreshold) {
                emit PriceDeviation(token, price, currentFeed.price, deviation);

                // Use fallback or reject if deviation too high
                if (deviation > MAX_DEVIATION_BPS) {
                    if (fallbackPrices[token] > 0) {
                        price = fallbackPrices[token];
                    } else {
                        revert("Price deviation too high");
                    }
                }
            }
        }

        // Update price feed
        latestPrices[token] = PriceFeed({
            price: price,
            timestamp: block.timestamp,
            confidence: confidence,
            decimals: config.decimals,
            active: true,
            source: source,
            sourceType: sourceType
        });

        // Update TWAP observations
        _updateTWAP(token, price);

        emit PriceUpdated(token, price, block.timestamp, source, sourceType);
    }

    function _aggregateAndUpdatePrice(address token) internal {
        address[] storage sources = tokenConfigs[token].priceSources;

        if (sources.length == 0) {
            return;
        }

        uint256 totalWeight;
        uint256 weightedSum;
        uint256 highestConfidence;

        for (uint256 i = 0; i < sources.length; i++) {
            PriceFeed storage sourceFeed = sourcePrices[token][sources[i]];

            if (sourceFeed.active && !_isSourceStale(sourceFeed)) {
                uint256 weight = sourceFeed.confidence;
                weightedSum += sourceFeed.price * weight;
                totalWeight += weight;

                if (sourceFeed.confidence > highestConfidence) {
                    highestConfidence = sourceFeed.confidence;
                }
            }
        }

        if (totalWeight > 0) {
            uint256 aggregatedPrice = weightedSum / totalWeight;
            _updatePrice(
                token,
                aggregatedPrice,
                highestConfidence,
                address(this),
                PriceSourceType.INTERNAL
            );
        }
    }

    function _updateTWAP(address token, uint256 price) internal {
        TWAPObservation[] storage observations = twapObservations[token];

        uint256 cumulativePrice;
        if (observations.length > 0) {
            TWAPObservation storage last = observations[observations.length - 1];
            uint256 timeElapsed = block.timestamp - last.timestamp;
            cumulativePrice = last.cumulativePrice + (last.price * timeElapsed);
        }

        // Add new observation
        observations.push(TWAPObservation({
            timestamp: block.timestamp,
            price: price,
            cumulativePrice: cumulativePrice
        }));

        // Trim old observations
        while (observations.length > MAX_OBSERVATIONS) {
            for (uint256 i = 0; i < observations.length - 1; i++) {
                observations[i] = observations[i + 1];
            }
            observations.pop();
        }
    }

    function _isStale(address token) internal view returns (bool) {
        PriceFeed storage feed = latestPrices[token];
        TokenConfig storage config = tokenConfigs[token];

        return block.timestamp - feed.timestamp > config.heartbeat;
    }

    function _isSourceStale(PriceFeed storage feed) internal view returns (bool) {
        return block.timestamp - feed.timestamp > 1 hours;
    }

    function _calculateDeviation(
        uint256 oldPrice,
        uint256 newPrice
    ) internal pure returns (uint256) {
        if (oldPrice == 0) return 0;

        uint256 diff = oldPrice > newPrice ? 
            oldPrice - newPrice : 
            newPrice - oldPrice;

        return (diff * BPS_DENOMINATOR) / oldPrice;
    }
}

contracts/src/TokenVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title TokenVesting
 * @notice Token vesting contract for X3 Chain with multiple vesting schedules
 * @dev Supports linear vesting, cliff vesting, and milestone-based vesting
 * 
 * Use cases:
 * - Team token vesting
 * - Investor allocations
 * - Advisor grants
 * - Community rewards
 * - Ecosystem fund distributions
 */
contract TokenVesting is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ═══════════════════════════════════════════════════════════════════════════
    // TYPES
    // ═══════════════════════════════════════════════════════════════════════════

    enum VestingType {
        LINEAR,           // Linear release over time
        CLIFF_LINEAR,     // Cliff then linear
        MILESTONE,        // Milestone-based releases
        INSTANT_CLIFF     // Instant release after cliff
    }

    struct VestingSchedule {
        uint256 scheduleId;
        address beneficiary;
        address token;
        uint256 totalAmount;
        uint256 releasedAmount;
        uint256 startTime;
        uint256 cliffDuration;
        uint256 vestingDuration;
        VestingType vestingType;
        bool revocable;
        bool revoked;
        uint256 revokedTime;
        string category; // "team", "investor", "advisor", "community"
    }

    struct Milestone {
        string description;
        uint256 releasePercent; // In BPS (10000 = 100%)
        bool completed;
        uint256 completedTime;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTANTS & ROLES
    // ═══════════════════════════════════════════════════════════════════════════

    bytes32 public constant VESTING_MANAGER_ROLE = keccak256("VESTING_MANAGER_ROLE");
    bytes32 public constant MILESTONE_MANAGER_ROLE = keccak256("MILESTONE_MANAGER_ROLE");

    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant MAX_SCHEDULES_PER_BENEFICIARY = 10;

    // ═══════════════════════════════════════════════════════════════════════════
    // STATE
    // ═══════════════════════════════════════════════════════════════════════════

    // Schedule counter
    uint256 public nextScheduleId;

    // All vesting schedules
    mapping(uint256 => VestingSchedule) public schedules;

    // Schedules per beneficiary
    mapping(address => uint256[]) public beneficiarySchedules;

    // Milestones per schedule (for MILESTONE type)
    mapping(uint256 => Milestone[]) public scheduleMilestones;

    // Total tokens locked per token address
    mapping(address => uint256) public totalLockedTokens;

    // Revoked tokens destination
    address public revokedTokensRecipient;

    // ═══════════════════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════════════════

    event VestingScheduleCreated(
        uint256 indexed scheduleId,
        address indexed beneficiary,
        address indexed token,
        uint256 totalAmount,
        VestingType vestingType,
        string category
    );

    event TokensReleased(
        uint256 indexed scheduleId,
        address indexed beneficiary,
        uint256 amount
    );

    event VestingRevoked(
        uint256 indexed scheduleId,
        address indexed beneficiary,
        uint256 unreleasedAmount
    );

    event MilestoneCompleted(
        uint256 indexed scheduleId,
        uint256 milestoneIndex,
        string description
    );

    event BeneficiaryChanged(
        uint256 indexed scheduleId,
        address indexed oldBeneficiary,
        address indexed newBeneficiary
    );

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════════

    constructor(address _revokedTokensRecipient) {
        require(_revokedTokensRecipient != address(0), "Invalid recipient");
        revokedTokensRecipient = _revokedTokensRecipient;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(VESTING_MANAGER_ROLE, msg.sender);
        _grantRole(MILESTONE_MANAGER_ROLE, msg.sender);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // VESTING SCHEDULE CREATION
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Create a linear vesting schedule
     */
    function createLinearVesting(
        address beneficiary,
        address token,
        uint256 totalAmount,
        uint256 startTime,
        uint256 vestingDuration,
        bool revocable,
        string calldata category
    ) external onlyRole(VESTING_MANAGER_ROLE) returns (uint256) {
        return _createSchedule(
            beneficiary,
            token,
            totalAmount,
            startTime,
            0, // no cliff
            vestingDuration,
            VestingType.LINEAR,
            revocable,
            category
        );
    }

    /**
     * @notice Create a cliff + linear vesting schedule
     */
    function createCliffVesting(
        address beneficiary,
        address token,
        uint256 totalAmount,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration,
        bool revocable,
        string calldata category
    ) external onlyRole(VESTING_MANAGER_ROLE) returns (uint256) {
        require(cliffDuration < vestingDuration, "Cliff must be < vesting");

        return _createSchedule(
            beneficiary,
            token,
            totalAmount,
            startTime,
            cliffDuration,
            vestingDuration,
            VestingType.CLIFF_LINEAR,
            revocable,
            category
        );
    }

    /**
     * @notice Create a milestone-based vesting schedule
     */
    function createMilestoneVesting(
        address beneficiary,
        address token,
        uint256 totalAmount,
        uint256 startTime,
        string[] calldata milestoneDescriptions,
        uint256[] calldata milestonePercents,
        bool revocable,
        string calldata category
    ) external onlyRole(VESTING_MANAGER_ROLE) returns (uint256) {
        require(
            milestoneDescriptions.length == milestonePercents.length,
            "Array length mismatch"
        );
        require(milestoneDescriptions.length > 0, "Need milestones");
        require(milestoneDescriptions.length <= 20, "Too many milestones");

        // Verify percents sum to 100%
        uint256 totalPercent;
        for (uint256 i = 0; i < milestonePercents.length; i++) {
            totalPercent += milestonePercents[i];
        }
        require(totalPercent == BPS_DENOMINATOR, "Percents must sum to 100%");

        uint256 scheduleId = _createSchedule(
            beneficiary,
            token,
            totalAmount,
            startTime,
            0,
            0, // No duration for milestone vesting
            VestingType.MILESTONE,
            revocable,
            category
        );

        // Create milestones
        for (uint256 i = 0; i < milestoneDescriptions.length; i++) {
            scheduleMilestones[scheduleId].push(Milestone({
                description: milestoneDescriptions[i],
                releasePercent: milestonePercents[i],
                completed: false,
                completedTime: 0
            }));
        }

        return scheduleId;
    }

    /**
     * @notice Create instant cliff vesting (all tokens released after cliff)
     */
    function createInstantCliffVesting(
        address beneficiary,
        address token,
        uint256 totalAmount,
        uint256 startTime,
        uint256 cliffDuration,
        bool revocable,
        string calldata category
    ) external onlyRole(VESTING_MANAGER_ROLE) returns (uint256) {
        return _createSchedule(
            beneficiary,
            token,
            totalAmount,
            startTime,
            cliffDuration,
            cliffDuration, // Duration equals cliff
            VestingType.INSTANT_CLIFF,
            revocable,
            category
        );
    }

    /**
     * @notice Batch create vesting schedules
     */
    function batchCreateLinearVesting(
        address[] calldata beneficiaries,
        address token,
        uint256[] calldata amounts,
        uint256 startTime,
        uint256 vestingDuration,
        bool revocable,
        string calldata category
    ) external onlyRole(VESTING_MANAGER_ROLE) returns (uint256[] memory) {
        require(beneficiaries.length == amounts.length, "Array mismatch");

        uint256[] memory scheduleIds = new uint256[](beneficiaries.length);

        for (uint256 i = 0; i < beneficiaries.length; i++) {
            scheduleIds[i] = _createSchedule(
                beneficiaries[i],
                token,
                amounts[i],
                startTime,
                0,
                vestingDuration,
                VestingType.LINEAR,
                revocable,
                category
            );
        }

        return scheduleIds;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // TOKEN RELEASE
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Release vested tokens for a schedule
     */
    function release(uint256 scheduleId) external nonReentrant {
        VestingSchedule storage schedule = schedules[scheduleId];

        require(schedule.beneficiary != address(0), "Schedule not found");
        require(!schedule.revoked, "Schedule revoked");
        require(
            msg.sender == schedule.beneficiary || hasRole(VESTING_MANAGER_ROLE, msg.sender),
            "Not authorized"
        );

        uint256 releasable = _computeReleasableAmount(scheduleId);
        require(releasable > 0, "Nothing to release");

        schedule.releasedAmount += releasable;
        totalLockedTokens[schedule.token] -= releasable;

        IERC20(schedule.token).safeTransfer(schedule.beneficiary, releasable);

        emit TokensReleased(scheduleId, schedule.beneficiary, releasable);
    }

    /**
     * @notice Release tokens for all of sender's schedules
     */
    function releaseAll() external nonReentrant {
        uint256[] storage userSchedules = beneficiarySchedules[msg.sender];

        for (uint256 i = 0; i < userSchedules.length; i++) {
            uint256 scheduleId = userSchedules[i];
            VestingSchedule storage schedule = schedules[scheduleId];

            if (schedule.revoked) continue;

            uint256 releasable = _computeReleasableAmount(scheduleId);
            if (releasable > 0) {
                schedule.releasedAmount += releasable;
                totalLockedTokens[schedule.token] -= releasable;

                IERC20(schedule.token).safeTransfer(msg.sender, releasable);

                emit TokensReleased(scheduleId, msg.sender, releasable);
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // MILESTONE MANAGEMENT
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Complete a milestone (releases associated tokens)
     */
    function completeMilestone(
        uint256 scheduleId,
        uint256 milestoneIndex
    ) external onlyRole(MILESTONE_MANAGER_ROLE) {
        VestingSchedule storage schedule = schedules[scheduleId];
        require(schedule.vestingType == VestingType.MILESTONE, "Not milestone vesting");
        require(!schedule.revoked, "Schedule revoked");

        Milestone[] storage milestones = scheduleMilestones[scheduleId];
        require(milestoneIndex < milestones.length, "Invalid index");
        require(!milestones[milestoneIndex].completed, "Already completed");

        milestones[milestoneIndex].completed = true;
        milestones[milestoneIndex].completedTime = block.timestamp;

        emit MilestoneCompleted(
            scheduleId,
            milestoneIndex,
            milestones[milestoneIndex].description
        );
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // REVOCATION
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Revoke a vesting schedule
     */
    function revoke(uint256 scheduleId) external onlyRole(VESTING_MANAGER_ROLE) {
        VestingSchedule storage schedule = schedules[scheduleId];

        require(schedule.beneficiary != address(0), "Schedule not found");
        require(schedule.revocable, "Not revocable");
        require(!schedule.revoked, "Already revoked");

        // Release any vested but unreleased tokens first
        uint256 releasable = _computeReleasableAmount(scheduleId);
        if (releasable > 0) {
            schedule.releasedAmount += releasable;
            IERC20(schedule.token).safeTransfer(schedule.beneficiary, releasable);
            emit TokensReleased(scheduleId, schedule.beneficiary, releasable);
        }

        // Calculate unreleased amount
        uint256 unreleased = schedule.totalAmount - schedule.releasedAmount;

        schedule.revoked = true;
        schedule.revokedTime = block.timestamp;

        if (unreleased > 0) {
            totalLockedTokens[schedule.token] -= unreleased;
            IERC20(schedule.token).safeTransfer(revokedTokensRecipient, unreleased);
        }

        emit VestingRevoked(scheduleId, schedule.beneficiary, unreleased);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // BENEFICIARY MANAGEMENT
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Transfer beneficiary rights to new address
     */
    function transferBeneficiary(
        uint256 scheduleId,
        address newBeneficiary
    ) external {
        VestingSchedule storage schedule = schedules[scheduleId];

        require(msg.sender == schedule.beneficiary, "Not beneficiary");
        require(newBeneficiary != address(0), "Invalid address");
        require(!schedule.revoked, "Schedule revoked");

        address oldBeneficiary = schedule.beneficiary;

        // Update beneficiary
        schedule.beneficiary = newBeneficiary;

        // Update beneficiary schedules mapping
        _removeScheduleFromBeneficiary(oldBeneficiary, scheduleId);
        beneficiarySchedules[newBeneficiary].push(scheduleId);

        emit BeneficiaryChanged(scheduleId, oldBeneficiary, newBeneficiary);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /**
     * @notice Get releasable amount for a schedule
     */
    function getReleasableAmount(uint256 scheduleId) external view returns (uint256) {
        return _computeReleasableAmount(scheduleId);
    }

    /**
     * @notice Get vested amount for a schedule
     */
    function getVestedAmount(uint256 scheduleId) external view returns (uint256) {
        return _computeVestedAmount(scheduleId);
    }

    /**
     * @notice Get all schedules for a beneficiary
     */
    function getBeneficiarySchedules(
        address beneficiary
    ) external view returns (uint256[] memory) {
        return beneficiarySchedules[beneficiary];
    }

    /**
     * @notice Get schedule details
     */
    function getSchedule(uint256 scheduleId) external view returns (VestingSchedule memory) {
        return schedules[scheduleId];
    }

    /**
     * @notice Get milestones for a schedule
     */
    function getMilestones(uint256 scheduleId) external view returns (Milestone[] memory) {
        return scheduleMilestones[scheduleId];
    }

    /**
     * @notice Get total releasable for beneficiary across all schedules
     */
    function getTotalReleasable(address beneficiary) external view returns (uint256 total) {
        uint256[] storage userSchedules = beneficiarySchedules[beneficiary];

        for (uint256 i = 0; i < userSchedules.length; i++) {
            if (!schedules[userSchedules[i]].revoked) {
                total += _computeReleasableAmount(userSchedules[i]);
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    function setRevokedTokensRecipient(address newRecipient) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newRecipient != address(0), "Invalid address");
        revokedTokensRecipient = newRecipient;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    function _createSchedule(
        address beneficiary,
        address token,
        uint256 totalAmount,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration,
        VestingType vestingType,
        bool revocable,
        string calldata category
    ) internal returns (uint256) {
        require(beneficiary != address(0), "Invalid beneficiary");
        require(token != address(0), "Invalid token");
        require(totalAmount > 0, "Invalid amount");
        require(startTime >= block.timestamp, "Start in past");
        require(
            beneficiarySchedules[beneficiary].length < MAX_SCHEDULES_PER_BENEFICIARY,
            "Too many schedules"
        );

        // Transfer tokens to contract
        IERC20(token).safeTransferFrom(msg.sender, address(this), totalAmount);

        uint256 scheduleId = nextScheduleId++;

        schedules[scheduleId] = VestingSchedule({
            scheduleId: scheduleId,
            beneficiary: beneficiary,
            token: token,
            totalAmount: totalAmount,
            releasedAmount: 0,
            startTime: startTime,
            cliffDuration: cliffDuration,
            vestingDuration: vestingDuration,
            vestingType: vestingType,
            revocable: revocable,
            revoked: false,
            revokedTime: 0,
            category: category
        });

        beneficiarySchedules[beneficiary].push(scheduleId);
        totalLockedTokens[token] += totalAmount;

        emit VestingScheduleCreated(
            scheduleId,
            beneficiary,
            token,
            totalAmount,
            vestingType,
            category
        );

        return scheduleId;
    }

    function _computeReleasableAmount(uint256 scheduleId) internal view returns (uint256) {
        VestingSchedule storage schedule = schedules[scheduleId];

        if (schedule.revoked) {
            return 0;
        }

        uint256 vested = _computeVestedAmount(scheduleId);
        return vested - schedule.releasedAmount;
    }

    function _computeVestedAmount(uint256 scheduleId) internal view returns (uint256) {
        VestingSchedule storage schedule = schedules[scheduleId];

        if (block.timestamp < schedule.startTime) {
            return 0;
        }

        if (schedule.vestingType == VestingType.MILESTONE) {
            return _computeMilestoneVested(scheduleId);
        }

        uint256 elapsed = block.timestamp - schedule.startTime;

        // Check cliff
        if (elapsed < schedule.cliffDuration) {
            return 0;
        }

        if (schedule.vestingType == VestingType.INSTANT_CLIFF) {
            // All tokens vest after cliff
            if (elapsed >= schedule.cliffDuration) {
                return schedule.totalAmount;
            }
            return 0;
        }

        // Linear vesting
        if (elapsed >= schedule.vestingDuration) {
            return schedule.totalAmount;
        }

        return (schedule.totalAmount * elapsed) / schedule.vestingDuration;
    }

    function _computeMilestoneVested(uint256 scheduleId) internal view returns (uint256) {
        VestingSchedule storage schedule = schedules[scheduleId];
        Milestone[] storage milestones = scheduleMilestones[scheduleId];

        uint256 vestedPercent;
        for (uint256 i = 0; i < milestones.length; i++) {
            if (milestones[i].completed) {
                vestedPercent += milestones[i].releasePercent;
            }
        }

        return (schedule.totalAmount * vestedPercent) / BPS_DENOMINATOR;
    }

    function _removeScheduleFromBeneficiary(
        address beneficiary,
        uint256 scheduleId
    ) internal {
        uint256[] storage userSchedules = beneficiarySchedules[beneficiary];

        for (uint256 i = 0; i < userSchedules.length; i++) {
            if (userSchedules[i] == scheduleId) {
                userSchedules[i] = userSchedules[userSchedules.length - 1];
                userSchedules.pop();
                break;
            }
        }
    }
}

contracts/X3AtomicExecutor.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.20;

/**
 * @title X3AtomicExecutor
 * @notice External chain bridge contract for X3 Atomic Execution verification.
 *
 * This contract allows external EVM chains (Ethereum, Polygon, Arbitrum, etc.)
 * to verify X3 PoAE (Proof of Atomic Execution) proofs and settle cross-chain
 * atomic bundles.
 *
 * ## Verification Flow
 *
 * 1. A relayer submits a PoAE proof from X3 chain.
 * 2. This contract verifies the proof structure.
 * 3. If valid, the bundle is marked as verified and side-effects can execute.
 *
 * ## Production Notes
 *
 * - v0: Structural verification only (hash checks, non-zero fields).
 * - v1: Add GRANDPA/Flash Finality light client verification.
 * - v2: Add ZK proof verification for full trustless settlement.
 */
contract X3AtomicExecutor {
    // ── Structs ────────────────────────────────────────────────────────────

    /// @notice Proof of Atomic Execution from X3 chain.
    struct AtomicExecutionProof {
        bytes32 bundleId;          // Unique bundle identifier
        bytes32 receiptRoot;       // Merkle root of execution receipts
        uint64  finalizedBlock;    // X3 block number where bundle was finalized
        bytes32 finalityCert;      // Hash of finality certificate (GRANDPA/Flash)
        bytes32 legsHash;          // Hash of original bundle legs
        uint32  legCount;          // Number of legs executed
    }

    /// @notice Status of a verified bundle.
    enum BundleStatus {
        Unknown,       // Not yet submitted
        Verified,      // Proof verified, awaiting settlement
        Settled,       // Side-effects executed on this chain
        Challenged,    // Proof under dispute
        Expired        // Past challenge window
    }

    /// @notice On-chain record for a verified bundle.
    struct BundleRecord {
        BundleStatus status;
        bytes32      receiptRoot;
        bytes32      finalityCert;
        uint64       finalizedBlock;
        uint32       legCount;
        uint256      verifiedAt;     // Block timestamp when verified
        address      relayer;        // Who submitted the proof
    }

    // ── State ──────────────────────────────────────────────────────────────

    /// @notice Verified bundles by bundle ID.
    mapping(bytes32 => BundleRecord) public bundles;

    /// @notice Challenge window in seconds (default 24 hours for optimistic path).
    uint256 public challengeWindow = 24 hours;

    /// @notice Contract owner (governance multisig).
    address public owner;

    /// @notice Light client contract for X3 finality verification (v1+).
    address public lightClient;

    /// @notice Trusted relayers (v0 authorized set).
    mapping(address => bool) public trustedRelayers;

    // ── Events ─────────────────────────────────────────────────────────────

    event BundleVerified(
        bytes32 indexed bundleId,
        bytes32 receiptRoot,
        bytes32 finalityCert,
        uint64  finalizedBlock,
        uint32  legCount,
        address relayer
    );

    event BundleSettled(
        bytes32 indexed bundleId,
        address settler
    );

    event BundleChallenged(
        bytes32 indexed bundleId,
        address challenger,
        string  reason
    );

    event RelayerUpdated(address relayer, bool trusted);
    event ChallengeWindowUpdated(uint256 newWindow);
    event LightClientUpdated(address newLightClient);

    // ── Modifiers ──────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "X3AE: not owner");
        _;
    }

    modifier onlyTrustedRelayer() {
        require(trustedRelayers[msg.sender], "X3AE: not trusted relayer");
        _;
    }

    // ── Constructor ────────────────────────────────────────────────────────

    constructor() {
        owner = msg.sender;
        trustedRelayers[msg.sender] = true;
    }

    // ── Core Functions ─────────────────────────────────────────────────────

    /**
     * @notice Submit and verify an atomic execution proof from X3 chain.
     * @param bundleId      Unique bundle identifier from X3.
     * @param receiptRoot   Merkle root of execution receipts.
     * @param finalizedBlock X3 block number where bundle was finalized.
     * @param finalityCert  Hash of finality certificate.
     * @param legsHash      Hash of original bundle legs.
     * @param legCount      Number of legs executed.
     * @return success       Whether the proof was accepted.
     */
    function submitAtomicBundle(
        bytes32 bundleId,
        bytes32 receiptRoot,
        uint64  finalizedBlock,
        bytes32 finalityCert,
        bytes32 legsHash,
        uint32  legCount
    ) external onlyTrustedRelayer returns (bool success) {
        require(bundles[bundleId].status == BundleStatus.Unknown, "X3AE: bundle exists");
        require(bundleId != bytes32(0), "X3AE: zero bundle ID");
        require(receiptRoot != bytes32(0), "X3AE: zero receipt root");
        require(finalityCert != bytes32(0), "X3AE: zero finality cert");
        require(legCount > 0, "X3AE: zero legs");

        // v0: Structural verification only.
        // v1: Call lightClient.verifyFinality(finalizedBlock, finalityCert)
        // v2: Verify ZK proof of execution

        // Compute proof hash for integrity
        bytes32 proofHash = keccak256(abi.encode(
            bundleId, receiptRoot, finalizedBlock, finalityCert, legsHash
        ));

        bundles[bundleId] = BundleRecord({
            status: BundleStatus.Verified,
            receiptRoot: receiptRoot,
            finalityCert: finalityCert,
            finalizedBlock: finalizedBlock,
            legCount: legCount,
            verifiedAt: block.timestamp,
            relayer: msg.sender
        });

        emit BundleVerified(
            bundleId,
            receiptRoot,
            finalityCert,
            finalizedBlock,
            legCount,
            msg.sender
        );

        return true;
    }

    /**
     * @notice Get the status and proof of a verified bundle.
     * @param bundleId The bundle to query.
     * @return record The bundle record.
     */
    function getAtomicExecutionProof(bytes32 bundleId)
        external
        view
        returns (BundleRecord memory record)
    {
        return bundles[bundleId];
    }

    /**
     * @notice Verify that a proof hash matches the stored bundle.
     * @param bundleId   Bundle to verify.
     * @param legsHash   Expected legs hash.
     * @return valid      Whether the proof is structurally valid.
     */
    function verify(bytes32 bundleId, bytes32 legsHash)
        external
        view
        returns (bool valid)
    {
        BundleRecord storage record = bundles[bundleId];
        if (record.status == BundleStatus.Unknown) return false;
        if (record.status == BundleStatus.Challenged) return false;

        // Recompute proof hash
        bytes32 proofHash = keccak256(abi.encode(
            bundleId,
            record.receiptRoot,
            record.finalizedBlock,
            record.finalityCert,
            legsHash
        ));

        // Proof is valid if it's verified and not challenged
        return record.status == BundleStatus.Verified ||
               record.status == BundleStatus.Settled;
    }

    /**
     * @notice Settle a verified bundle (execute side-effects).
     * @dev Can only be called after the challenge window expires.
     * @param bundleId Bundle to settle.
     */
    function settleBundleOptimistic(bytes32 bundleId) external {
        BundleRecord storage record = bundles[bundleId];
        require(record.status == BundleStatus.Verified, "X3AE: not verified");
        require(
            block.timestamp >= record.verifiedAt + challengeWindow,
            "X3AE: challenge window active"
        );

        record.status = BundleStatus.Settled;

        emit BundleSettled(bundleId, msg.sender);
    }

    /**
     * @notice Challenge a verified bundle.
     * @dev Must be called within the challenge window.
     * @param bundleId Bundle to challenge.
     * @param reason   Description of the challenge.
     */
    function challengeBundle(bytes32 bundleId, string calldata reason) external {
        BundleRecord storage record = bundles[bundleId];
        require(record.status == BundleStatus.Verified, "X3AE: not challengeable");
        require(
            block.timestamp < record.verifiedAt + challengeWindow,
            "X3AE: window expired"
        );

        record.status = BundleStatus.Challenged;

        emit BundleChallenged(bundleId, msg.sender, reason);
    }

    // ── Admin Functions ────────────────────────────────────────────────────

    function setTrustedRelayer(address relayer, bool trusted) external onlyOwner {
        trustedRelayers[relayer] = trusted;
        emit RelayerUpdated(relayer, trusted);
    }

    function setChallengeWindow(uint256 newWindow) external onlyOwner {
        require(newWindow >= 1 hours, "X3AE: window too short");
        require(newWindow <= 7 days, "X3AE: window too long");
        challengeWindow = newWindow;
        emit ChallengeWindowUpdated(newWindow);
    }

    function setLightClient(address _lightClient) external onlyOwner {
        lightClient = _lightClient;
        emit LightClientUpdated(_lightClient);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "X3AE: zero address");
        owner = newOwner;
    }
}

